// Independent diagnostic only. Private access permits forcing redundant
// inward-row classifications on a disposable Runtime; no production edit.
#include <bits/stdc++.h>
#include <json/json.hpp>
#define private public
#include "coarse_die/Execution.hh"
#undef private
using namespace coarse_die; using nlohmann::json;
json load(const std::string&p){std::ifstream f(p);json v;f>>v;return v;}
const char* path(ArbitrationDiagnostics::Path p){switch(p){case ArbitrationDiagnostics::Path::Empty:return "empty";case ArbitrationDiagnostics::Path::Singleton:return "singleton";case ArbitrationDiagnostics::Path::Packing:return "packing";case ArbitrationDiagnostics::Path::SignedLP:return "signed_lp";case ArbitrationDiagnostics::Path::Ratio:return "ratio";}return "?";}
json inspect(Runtime&r){auto a=r.last_arbitration();json rows=json::array();for(auto&[h,e]:r.executions_){json live=json::array();for(auto&l:e.activities)if(!l.done&&l.epoch_index==e.epoch)live.push_back({{"id",l.definition.id},{"rate",l.rate},{"alpha",l.alpha},{"progress_exact",([&](){std::ostringstream o;o<<std::scientific<<std::setprecision(21)<<l.progress;return o.str();})()}});rows.push_back({{"handle",h},{"epoch",e.epoch},{"credit",e.credit},{"capacity",e.credit_capacity},{"live",live}});}return {{"now_ns",r.now_ns()},{"path",path(a.path)},{"activities",a.activities},{"rows",a.constraint_rows},{"pivots",a.pivots},{"tangent_rounds",a.tangent_rounds},{"executions",rows}};}
int main(int argc,char**argv){if(argc!=2)return 2;auto in=load(std::string(argv[1])+"/inputs.json");auto hw=resolve_hardware(in.at("config"));std::vector<std::shared_ptr<const Plan>>plans;for(auto&t:in.at("tasks"))plans.push_back(compile(hw,t));Runtime r(hw);for(unsigned i=0;i<8;++i){auto owner=i/2+1;r.submit(plans.at(i%2),Owner{i+1,owner,owner,1},0);}json result;result["initial"]=inspect(r);for(unsigned step=0;step<2;++step){auto t=r.next_event();if(!t)throw std::runtime_error("no event");r.advance_to(*t);result["public_events"].push_back(inspect(r));}auto s=r.export_snapshot();result["snapshot_matches_capture"]=s==load(std::string(argv[1])+"/failed-snapshot.json");try{auto c=Runtime::import_snapshot(hw,s);result["original_import"]="unexpected pass";}catch(const std::exception&e){result["original_import"]=e.what();}auto legacy=s;legacy.erase("allocation_state");auto current=Runtime::import_snapshot(hw,legacy);result["current_rebuild"]=inspect(*current);for(auto&[h,e]:current->executions_)if(h%2==0)e.credit[0]=e.credit_capacity[0];current->allocate();result["diagnostic_force_norm_input_high_only"]=inspect(*current);result["disclaimer"]="Forced credit is an inconsistent private diagnostic state, not a valid snapshot/import. It changes only redundant inward constraints to identify allocation-path sensitivity.";std::cout<<result.dump(2)<<"\n";}
